/**
 * Realm spawn bands (pure). A side's zones and the roads out to them spawn by the campaign's quest order
 * (src/data/regions/hc/zoneBands.gen.ts, generated by tools/playthrough/bands.ts): each group has tiers that start
 * at the expected hero level of its first visit and step up at later visits. A tier applies once main quest
 * `step` of Act I is done by the side's own class or by the host's class (so a sibling class, or any class in
 * co-op, walking another side still sees it grow; both campaigns share the same expected curve per main index).
 * Groups the table doesn't know keep their old fixed band (`fallback`: zone 2 → L1, 3 → L5, 4 → L9; guards by kind).
 */
import { ACT1_MAINS, SIDE_CLASS, ZONE_BANDS, type ZoneTier } from '@/data/regions/hc/zoneBands.gen';

/** A level band that applies once Act I main quest `step` (1-based) is done (later tiers win). */
export interface LevelTier { step: number; level: [number, number]; elite?: boolean }
export interface Banded { level: [number, number]; elite?: boolean; tiers?: LevelTier[]; cls?: string }
/** whether Act I main `step` is done by the side's class (`cls`) or by the host */
export type StepDone = (cls: string | undefined, step: number) => boolean;

/** patrols and camps lead elites only from this level (Claude 3: no elite walls below ~L8) */
const ELITE_FROM = 8;

/** The tiers of a group: the table's, or the old fixed floor. */
function groupTiers(group: string, fallback: number): ZoneTier[] {
  return ZONE_BANDS[group] ?? [{ floor: Math.max(1, fallback) }];
}

/** The zone-number floor (zone 2 → L1, 3 → L5, 4 → L9). */
export const zoneFloor = (zone: number): number => Math.max(1, 1 + (zone - 2) * 4);

/**
 * Level (and elite) of a spawn in `group` (zone n of a side, a realm's gate road, an optional area's approach),
 * from a tier's floor. `eliteGuard`: an approach guard that leads with an elite once its floor reaches L8.
 */
export function banded(group: string, fallback: number, kind: 'zone' | 'patrol' | 'camp-near' | 'camp' | 'guard', eliteGuard = false): Banded {
  const one = (f: number): { level: [number, number]; elite?: boolean } =>
    kind === 'zone' ? { level: [f, f + 2] }
      : kind === 'patrol' ? { level: [f + 1, f + 2], elite: f + 1 >= ELITE_FROM }
        : kind === 'camp-near' ? { level: [Math.max(1, f - 1), Math.max(1, f - 1) + 1] }
          : kind === 'guard' ? { level: [f, f + 1], elite: eliteGuard && f >= ELITE_FROM }
            : { level: [f, f + 1] };
  const [first, ...rest] = groupTiers(group, fallback);
  const cls = SIDE_CLASS[group.split('-').slice(0, 2).join('-')];
  return { ...one(first.floor), cls, tiers: rest.length ? rest.map((t) => ({ step: t.step!, ...one(t.floor) })) : undefined };
}

/** The tier in force: the last whose step is done. */
function current(z: Banded, done: StepDone): { level: [number, number]; elite?: boolean } {
  let t: { level: [number, number]; elite?: boolean } = z;
  for (const x of z.tiers ?? []) if (done(z.cls, x.step)) t = x;
  return t;
}

/** The level band in force for a spawn zone. */
export const levelAt = (z: Banded, done: StepDone): [number, number] => current(z, done).level;
/** Whether a spawn zone leads with an elite now. */
export const eliteAt = (z: Banded, done: StepDone): boolean => !!current(z, done).elite;

/** The live StepDone: the side's class or the host's class has completed that Act I main quest. */
export function stepDone(host: string | null, completed: (quest: string) => boolean): StepDone {
  return (cls, step) => [cls, host].some((c) => { const q = c ? ACT1_MAINS[c]?.[step - 1] : undefined; return !!q && completed(q); });
}
